import { apiUser, requireProjectAccess, jsonError } from '@/lib/api-auth';
import { db, ensureSchema } from '@/lib/db';
import { DEFAULT_RULES } from '@/lib/classify';
import { getSetting } from '@/lib/ops';
import { projectId } from '@/lib/projects';

export const dynamic = 'force-dynamic';

type CacheEntry = { json: string; timestamp: number };
const memoryCache = new Map<string, CacheEntry>();
const CACHE_TTL_MS = 120_000;

export function invalidateOpsCache(project?: string) {
  if (!project) {
    memoryCache.clear();
    return;
  }
  for (const k of memoryCache.keys()) {
    if (k.startsWith(`ops:${project}:`)) {
      memoryCache.delete(k);
    }
  }
}

export async function GET(request: Request) {
  const url = new URL(request.url);
  const rawProject = url.searchParams.get('projectId');
  const access = typeof requireProjectAccess === 'function'
    ? await requireProjectAccess(request, rawProject, 'read')
    : (await apiUser() ? { ok: true, status: 200, error: '', context: { projectId: String(rawProject || 'qicui') } } : { ok: false, status: 401, error: '请先登录' });
  if (!access.ok) return jsonError(access.error!, access.status!);
  const project = access.context!.projectId;
  await ensureSchema();
  const d1 = db();
  const visibility = url.searchParams.get('visibility') || '';
  const fresh = url.searchParams.get('fresh') === '1' || Boolean(url.searchParams.get('_t'));
  const cacheKey = `ops:${project}:${visibility}`;

  if (fresh) {
    for (const k of memoryCache.keys()) {
      if (k.startsWith(`ops:${project}:`)) {
        memoryCache.delete(k);
      }
    }
  } else {
  const cached = memoryCache.get(cacheKey);
  if (cached && Date.now() - cached.timestamp < CACHE_TTL_MS) {
    return new Response(cached.json, {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'Cache-Control': 'private, max-age=60, stale-while-revalidate=180',
        'X-Cache': 'HIT',
      },
    });
  }
  }

  const supplierSql = `SELECT id,note_id AS noteId,note_url AS noteUrl,creator,planned_content AS plannedContent,
    comment_format AS commentFormat,visibility,matched_content AS matchedContent,verified_at AS verifiedAt
    FROM supplier_comments WHERE project_id=? ${visibility ? 'AND visibility=?' : ''} ORDER BY COALESCE(verified_at,'') DESC,id DESC LIMIT 120`;

  const [
    jobs,
    logs,
    supplier,
    supplierFeatures,
    categories,
    rules,
    acceptance,
    goals,
    growth,
    reviewRules,
    reports,
    completedJobsRow,
  ] = await Promise.all([
    d1.prepare('SELECT id,type,title,status,progress,total,succeeded,failed,message,created_at AS createdAt,finished_at AS finishedAt FROM jobs WHERE project_id=? ORDER BY created_at DESC LIMIT 40').bind(project).all(),
    d1.prepare('SELECT id,action,target_type AS targetType,target_id AS targetId,detail,actor_user_id AS actorUserId,created_at AS createdAt FROM action_logs WHERE project_id=? ORDER BY created_at DESC LIMIT 60').bind(project).all(),
    visibility ? d1.prepare(supplierSql).bind(project, visibility).all() : d1.prepare(supplierSql).bind(project).all(),
    d1.prepare(`SELECT visibility,COUNT(*) AS count,ROUND(AVG(LENGTH(planned_content)),1) AS avgLength,
      ROUND(AVG(CASE WHEN planned_content LIKE '%，%' OR planned_content LIKE '%,%' THEN 1.0 ELSE 0 END)*100,1) AS commaRate,
      ROUND(AVG(CASE WHEN LENGTH(planned_content)>=18 OR planned_content GLOB '*[0-9]*' THEN 1.0 ELSE 0 END)*100,1) AS detailRate
      FROM supplier_comments WHERE project_id=? AND visibility!='待核验' GROUP BY visibility`).bind(project).all(),
    d1.prepare(`SELECT category,sentiment,COUNT(*) AS count FROM key_comments WHERE project_id=? AND disappeared_at IS NULL GROUP BY category,sentiment ORDER BY count DESC LIMIT 12`).bind(project).all(),
    getSetting('rules', DEFAULT_RULES, project),
    getSetting('acceptance', { reportCount: 200, baseCount: 30, brandTopRate: 0.4, freshnessHours: 24, supplierSimilarity: 0.58 }, project),
    getSetting('goals', { workTarget: 0, workCompleted: 0, monthlyTarget: 0, quarterlyTarget: 0, publishTarget: 0, budgetTarget: 0, commentTarget: 0 }, project),
    getSetting('growth', { watchKeywords: [], inspirations: [], seedNoteIds: [], thresholds: { breakoutInteractions: 1000, seedScore: 65, ctr: 0.15, cpuv: 0.7 } }, project),
    d1.prepare(`SELECT id,name,keywords,sentiment,category,action,priority,enabled,updated_at AS updatedAt FROM review_rules WHERE project_id=? ORDER BY priority,updated_at DESC`).bind(project).all(),
    d1.prepare(`SELECT id,title,period_start AS periodStart,period_end AS periodEnd,status,summary_json AS summaryJson,created_at AS createdAt,updated_at AS updatedAt FROM saved_reports WHERE project_id=? ORDER BY updated_at DESC LIMIT 30`).bind(project).all(),
    d1.prepare(`SELECT COUNT(*) AS count FROM jobs WHERE project_id=? AND status='已完成'`).bind(project).first<{ count: number }>(),
  ]);

  const actualCompleted = Number(completedJobsRow?.count || 0);
  const resolvedGoals = {
    ...goals,
    workCompleted: actualCompleted,
  };

  const payload = {
    ok: true,
    jobs: jobs.results,
    logs: logs.results,
    supplier: supplier.results,
    supplierFeatures: supplierFeatures.results,
    categories: categories.results,
    reviewRules: reviewRules.results,
    reports: reports.results,
    settings: { rules, acceptance, goals: resolvedGoals, growth },
  };

  const jsonStr = JSON.stringify(payload);
  memoryCache.set(cacheKey, { json: jsonStr, timestamp: Date.now() });

  return new Response(jsonStr, {
    status: 200,
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': fresh ? 'no-cache, no-store, must-revalidate' : 'private, max-age=60, stale-while-revalidate=180',
      'X-Cache': 'MISS',
    },
  });
}

import { getAuthenticatedUser, requireProjectAccess, jsonError } from '@/lib/api-auth';
import { db, ensureSchema } from '@/lib/db';
import { projectId } from '@/lib/projects';
import { projectReadiness } from '@/lib/onboarding';
import { transformMappedRows, type FieldMappingRule, type MappingContext } from '@/lib/field-mapping';

export const dynamic = 'force-dynamic';
const text = (value: unknown) => String(value || '').trim();
const slug = (value: string) =>
  value
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 32) || `project-${crypto.randomUUID().slice(0, 8)}`;

export async function GET(request?: Request) {
  const user = await getAuthenticatedUser(request);
  if (!user) return jsonError('请先登录', 401);

  await ensureSchema();
  const d1 = db();

  const url = request ? new URL(request.url) : null;
  const targetProjectId = url?.searchParams.get('projectId');
  if (targetProjectId) {
    const access = await requireProjectAccess(request!, targetProjectId, 'read');
    if (!access.ok) return jsonError(access.error!, access.status!);
    const pId = access.context!.projectId;

    const [project, members, availableUsers, onboarding] = await Promise.all([
      d1.prepare(`SELECT p.id, p.name, p.spu, p.brand, p.category, p.description, p.status, p.color,
        p.start_at AS startAt, p.end_at AS endAt, p.org_id AS orgId, p.department_id AS departmentId,
        p.client_id AS clientId, p.owner_id AS ownerId, p.template_id AS templateId,
        p.is_archived AS isArchived, p.onboarding_status AS onboardingStatus,
        p.updated_at AS updatedAt,
        d.name AS departmentName, c.name AS clientName, t.name AS templateName
        FROM projects p
        LEFT JOIN departments d ON d.id=p.department_id
        LEFT JOIN clients c ON c.id=p.client_id
        LEFT JOIN project_templates t ON t.id=p.template_id
        WHERE p.id=?`).bind(pId).first(),
      d1.prepare(`SELECT pm.id, pm.project_id AS projectId, pm.user_id AS userId, pm.role,
        COALESCE(u.name, pm.user_id) AS name, COALESCE(u.email, '') AS email, u.department_id AS departmentId
        FROM project_members pm
        LEFT JOIN users u ON u.id=pm.user_id
        WHERE pm.project_id=? ORDER BY pm.created_at ASC`).bind(pId).all(),
      d1.prepare('SELECT id, name, email, role, department_id AS departmentId FROM users ORDER BY name').all(),
      d1.prepare('SELECT current_step AS currentStep, completed_steps_json AS completedStepsJson, selected_template_id AS selectedTemplateId FROM project_onboarding WHERE project_id=?').bind(pId).first(),
    ]);

    return Response.json({
      ok: true,
      project,
      members: members.results || [],
      availableUsers: availableUsers.results || [],
      onboarding,
      currentUser: access.context!.user,
      projectRole: access.context!.projectRole,
      readiness: await projectReadiness(pId, (() => { try { return JSON.parse((onboarding as { completedStepsJson?: string })?.completedStepsJson || '[]'); } catch { return []; } })()),
    });
  }

  const isPlatformAdmin = user.role === 'platform_admin';
  const filterClause = isPlatformAdmin
    ? '1=1'
    : `(p.id IN (SELECT project_id FROM project_members WHERE user_id='${user.userId}') OR p.created_by='${user.userId}' OR p.owner_id='${user.userId}')`;

  const [projects, sources, departments, clients, templates] = await Promise.all([
    d1
      .prepare(
        `SELECT p.id, p.name, p.spu, p.brand, p.category, p.description, p.status, p.color,
        p.start_at AS startAt, p.end_at AS endAt, p.org_id AS orgId, p.department_id AS departmentId,
        p.client_id AS clientId, p.owner_id AS ownerId, p.template_id AS templateId,
        p.is_archived AS isArchived, p.onboarding_status AS onboardingStatus,
        p.updated_at AS updatedAt,
        COUNT(DISTINCT pn.note_id) AS noteCount,
        SUM(CASE WHEN pn.status='符合且能汇报' THEN 1 ELSE 0 END) AS reportableCount,
        d.name AS departmentName,
        c.name AS clientName,
        t.name AS templateName
        FROM projects p
        LEFT JOIN project_notes pn ON pn.project_id=p.id
        LEFT JOIN departments d ON d.id=p.department_id
        LEFT JOIN clients c ON c.id=p.client_id
        LEFT JOIN project_templates t ON t.id=p.template_id
        WHERE ${filterClause}
        GROUP BY p.id
        ORDER BY CASE p.status WHEN '进行中' THEN 0 WHEN '筹备中' THEN 1 WHEN '已结束' THEN 2 ELSE 3 END, p.updated_at DESC`
      )
      .all(),
    d1
      .prepare(
        `SELECT s.id, s.project_id AS projectId, s.type, s.name, s.spreadsheet, s.sheet_id AS sheetId,
        s.range, s.kind, s.sync_frequency AS syncFrequency, s.status, s.last_synced_at AS lastSyncedAt,
        s.last_row_count AS lastRowCount, s.mapping_json AS mappingJson, s.last_error AS lastError,
        s.updated_at AS updatedAt
        FROM data_sources s
        JOIN projects p ON p.id=s.project_id
        WHERE ${filterClause}
        ORDER BY s.updated_at DESC`
      )
      .all(),
    d1.prepare('SELECT id, name FROM departments ORDER BY name').all(),
    d1.prepare('SELECT id, name, industry FROM clients ORDER BY name').all(),
    d1.prepare('SELECT id, name, description, icon, modules_json AS modulesJson FROM project_templates ORDER BY name').all(),
  ]);

  return Response.json({
    ok: true,
    projects: projects.results,
    sources: sources.results,
    metadata: {
      departments: departments.results,
      clients: clients.results,
      templates: templates.results,
      currentUser: user,
    },
  });
}

export async function POST(request: Request) {
  let body: Record<string, unknown> = {};
  try {
    body = (await request.json()) as Record<string, unknown>;
  } catch {
    return jsonError('无效的请求数据');
  }

  const action = text(body.action);
  const now = new Date().toISOString();
  await ensureSchema();
  const d1 = db();

  if (action === 'create') {
    const user = await getAuthenticatedUser(request);
    if (!user) return jsonError('请先登录', 401);

    const name = text(body.name);
    if (!name) return jsonError('请填写项目名称');

    const templateId = text(body.templateId) || 'general_workbench';
    const departmentId = text(body.departmentId) || 'dept-general';
    const clientId = text(body.clientId) || null;
    const ownerId = text(body.ownerId) || user.userId;
    const status = text(body.status) || '筹备中';
    const color = text(body.color) || '#1769d5';
    const description = text(body.description);
    const spu = text(body.spu);
    const brand = text(body.brand);
    const category = text(body.category);
    const startAt = text(body.startAt) || null;
    const endAt = text(body.endAt) || null;

    let id = text(body.id) ? slug(text(body.id)) : slug(name);
    const exists = await d1.prepare('SELECT id FROM projects WHERE id=?').bind(id).first();
    if (exists) id = `${id}-${Date.now().toString(36).slice(-4)}`;

    await d1
      .prepare(
        `INSERT INTO projects(id, name, spu, brand, category, description, status, color, start_at, end_at,
        org_id, department_id, client_id, owner_id, template_id, is_archived, onboarding_status, created_by, created_at, updated_at)
        VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'org-default', ?, ?, ?, ?, 0, 'source', ?, ?, ?)`
      )
      .bind(id, name, spu, brand, category, description, status, color, startAt, endAt, departmentId, clientId, ownerId, templateId, user.userId, now, now)
      .run();

    // Add creator as project administrator
    await d1
      .prepare(`INSERT OR IGNORE INTO project_members(id, project_id, user_id, role, created_at, updated_at) VALUES(?, ?, ?, 'project_admin', ?, ?)`)
      .bind(`${id}:${user.userId}`, id, user.userId, now, now)
      .run();

    // Initialize onboarding state
    await d1
      .prepare(`INSERT OR IGNORE INTO project_onboarding(project_id, current_step, completed_steps_json, selected_template_id, updated_at) VALUES(?, 'source', '["template"]', ?, ?)`)
      .bind(id, templateId, now)
      .run();

    // Create default dashboard from template
    const templateRow = await d1.prepare('SELECT default_dashboard_json FROM project_templates WHERE id=?').bind(templateId).first<{ default_dashboard_json: string }>();
    let cards: Array<Record<string, unknown>> = [];
    if (templateRow?.default_dashboard_json) {
      try {
        const parsed = JSON.parse(templateRow.default_dashboard_json) as { cards?: Array<Record<string, unknown>> };
        cards = parsed.cards || [];
      } catch {}
    }

    const dashboardId = `dash-${id}-default`;
    await d1
      .prepare(`INSERT OR IGNORE INTO dashboards(id, project_id, name, is_default, version, layout_json, status, created_at, updated_at) VALUES(?, ?, '默认看板', 1, 1, '[]', 'published', ?, ?)`)
      .bind(dashboardId, id, now, now)
      .run();

    for (const [index, card] of cards.entries()) {
      const cardId = `card-${id}-${card.id || index + 1}`;
      await d1
        .prepare(`INSERT OR IGNORE INTO dashboard_cards(id, dashboard_id, project_id, title, type, metric_keys_json, config_json, sort_order, created_at, updated_at) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
        .bind(cardId, dashboardId, id, String(card.title || '指标卡'), String(card.type || 'metric_card'), JSON.stringify(card.metric ? [card.metric] : []), JSON.stringify(card), index, now, now)
        .run();
    }

    // Only configure marketing/comment pipelines if this project explicitly selected those templates!
    if (templateId === 'content_marketing') {
      const pipelines = [
        ['viral', '口碑爆文维护', 200],
        ['value_scan', '价值内容扫描', 60],
        ['commercial', '商业内容执行', 300],
      ] as const;
      await d1.batch(
        pipelines.map(([key, label, target]) =>
          d1.prepare(`INSERT INTO project_pipelines(id,project_id,key,name,target_count) VALUES(?,?,?,?,?)`).bind(`${id}:${key}`, id, key, label, target)
        )
      );
      if (brand || spu) {
        const rules = {
          brands: [brand, spu].filter(Boolean),
          competitors: [],
          positiveWords: ['好用', '推荐', '喜欢', '有效', '值得'],
          negativeWords: ['不好', '踩雷', '失望', '问题', '投诉'],
          questionWords: ['吗', '怎么', '多少', '哪里买'],
          sellingWords: ['出售', '加微', '低价出'],
          irrelevantWords: ['互赞', '打卡', '路过'],
          deleteCompetitorMentions: false,
        };
        await d1
          .prepare(`INSERT INTO project_settings(id,project_id,key,value,updated_at) VALUES(?,?,?,?,?)`)
          .bind(`${id}:rules`, id, 'rules', JSON.stringify(rules), now)
          .run();
      }
    } else if (templateId === 'comment_qc') {
      await d1
        .prepare(`INSERT INTO project_settings(id,project_id,key,value,updated_at) VALUES(?,?,?,?,?)`)
        .bind(`${id}:acceptance`, id, 'acceptance', JSON.stringify({ reportCount: 200, baseCount: 30, brandTopRate: 0.4, freshnessHours: 24, supplierSimilarity: 0.58 }), now)
        .run();
    }

    return Response.json({ ok: true, id, templateId });
  }

  // All other actions require existing project access check
  const rawId = body.projectId;
  const access = await requireProjectAccess(request, rawId, action === 'delete' ? 'admin' : action === 'restore' ? 'restore' : 'manage');
  if (!access.ok) return jsonError(access.error!, access.status!);

  const id = access.context!.projectId;

  let readiness: Awaited<ReturnType<typeof projectReadiness>> | undefined;
  if (body.onboardingStatus === 'ready') {
    const previous = await d1.prepare('SELECT completed_steps_json FROM project_onboarding WHERE project_id=?').bind(id).first<{ completed_steps_json: string }>();
    let savedSteps: string[] = []; try { savedSteps = JSON.parse(previous?.completed_steps_json || '[]'); } catch {}
    const requestedSteps = [...savedSteps.filter(s => s === 'skip:members'), ...(Array.isArray(body.completedSteps) ? body.completedSteps.map(String) : [])];
    readiness = await projectReadiness(id, requestedSteps);
    if (!readiness.ready) return Response.json({ ok: false, error: '初始化必要条件未完成：' + readiness.blockedSteps.join('、'), readiness }, { status: 400 });
  }

  if (action === 'update_onboarding') {
    const statusVal = text(body.onboardingStatus) || 'pending';
    const completedSteps = readiness?.completedSteps || (Array.isArray(body.completedSteps) ? body.completedSteps.filter(s => s === 'skip:members') : []);
    const stepsJson = JSON.stringify(completedSteps);
    await d1.prepare(`UPDATE projects SET onboarding_status=?, updated_at=? WHERE id=?`).bind(statusVal, now, id).run();
    await d1.prepare(`UPDATE project_onboarding SET current_step=?, completed_steps_json=?, updated_at=? WHERE project_id=?`).bind(statusVal, stepsJson, now, id).run();
    return Response.json({ ok: true, id, onboardingStatus: statusVal, completedSteps });
  }

  if (action === 'update') {
    if (body.onboardingStatus !== undefined && body.name === undefined) {
      const statusVal = text(body.onboardingStatus) || 'ready';
      await d1.prepare(`UPDATE projects SET onboarding_status=?, updated_at=? WHERE id=?`).bind(statusVal, now, id).run();
      await d1.prepare(`UPDATE project_onboarding SET current_step='ready', completed_steps_json=?, updated_at=? WHERE project_id=?`).bind(JSON.stringify(readiness?.completedSteps || []), now, id).run();
      return Response.json({ ok: true, id, onboardingStatus: statusVal });
    }

    const existing = await d1.prepare('SELECT * FROM projects WHERE id=?').bind(id).first<Record<string, unknown>>();
    if (!existing) return jsonError('项目不存在', 404);

    const name = body.name !== undefined ? text(body.name) : (existing.name as string);
    if (!name) return jsonError('请填写项目名称');
    const spu = body.spu !== undefined ? text(body.spu) : (existing.spu as string);
    const brand = body.brand !== undefined ? text(body.brand) : (existing.brand as string);
    const category = body.category !== undefined ? text(body.category) : (existing.category as string);
    const description = body.description !== undefined ? text(body.description) : (existing.description as string);
    const status = body.status !== undefined ? text(body.status) : (existing.status as string);
    const color = body.color !== undefined ? text(body.color) : (existing.color as string);
    const departmentId = body.departmentId !== undefined ? text(body.departmentId) : (existing.department_id as string);
    const clientId = body.clientId !== undefined ? text(body.clientId) || null : (existing.client_id as string | null);
    const ownerId = body.ownerId !== undefined ? text(body.ownerId) : (existing.owner_id as string);
    const startAt = body.startAt !== undefined ? text(body.startAt) || null : (existing.start_at as string | null);
    const endAt = body.endAt !== undefined ? text(body.endAt) || null : (existing.end_at as string | null);
    const onboardingStatus = body.onboardingStatus !== undefined ? text(body.onboardingStatus) : (existing.onboarding_status as string);

    await d1
      .prepare(
        `UPDATE projects SET name=?, spu=?, brand=?, category=?, description=?, status=?, color=?,
        department_id=?, client_id=?, owner_id=?, start_at=?, end_at=?, onboarding_status=?, updated_at=? WHERE id=?`
      )
      .bind(
        name,
        spu,
        brand,
        category,
        description,
        status || '进行中',
        color || '#1769d5',
        departmentId || 'dept-general',
        clientId,
        ownerId || access.context!.user.userId,
        startAt,
        endAt,
        onboardingStatus || 'pending',
        now,
        id
      )
      .run();

    if (body.onboardingStatus === 'ready') {
      await d1.prepare(`UPDATE project_onboarding SET current_step='ready', completed_steps_json=?, updated_at=? WHERE project_id=?`).bind(JSON.stringify(readiness?.completedSteps || []), now, id).run();
    }
    return Response.json({ ok: true, id });
  }

  if (action === 'archive') {
    await d1.prepare(`UPDATE projects SET is_archived=1, status='已归档', archived_at=?, updated_at=? WHERE id=?`).bind(now, now, id).run();
    return Response.json({ ok: true, id, status: '已归档' });
  }

  if (action === 'restore') {
    await d1.prepare(`UPDATE projects SET is_archived=0, status='进行中', archived_at=NULL, updated_at=? WHERE id=?`).bind(now, id).run();
    return Response.json({ ok: true, id, status: '进行中' });
  }

  if (action === 'delete') {
    if (!access.context!.isPlatformAdmin) {
      return jsonError('仅平台超级管理员可执行彻底删除操作', 403);
    }
    await d1.batch([
      d1.prepare('DELETE FROM project_members WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM data_sources WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM dashboards WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM dashboard_cards WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM datasets WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM dataset_rows WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM sync_jobs WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM note_project_profiles WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM project_notes WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM supplier_comments WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM project_settings WHERE project_id=?').bind(id),
      d1.prepare('DELETE FROM projects WHERE id=?').bind(id),
    ]);
    return Response.json({ ok: true, id, deleted: true });
  }

  if (action === 'save_source') {
    const sourceId = text(body.id) || crypto.randomUUID();
    const ownership = await d1.prepare('SELECT project_id FROM data_sources WHERE id=?').bind(sourceId).first<{ project_id: string }>();
    if (ownership && ownership.project_id !== id) return jsonError('数据源不属于当前项目', 403);
    const name = text(body.name);
    if (!name) return jsonError('请填写数据源名称');
    let mapping = '{}';
    try {
      mapping = typeof body.mappingJson === 'string' ? JSON.stringify(JSON.parse(body.mappingJson)) : JSON.stringify(body.mappingJson || {});
    } catch {
      return jsonError('字段映射必须是合法 JSON');
    }
    const parsedMapping = JSON.parse(mapping) as { rules?: FieldMappingRule[]; context?: MappingContext };
    const rules = Array.isArray(parsedMapping) ? parsedMapping : parsedMapping.rules || [];
    const mappingErrors = transformMappedRows([], rules).errors;
    if (mappingErrors.length) return jsonError(mappingErrors.join('；'));
    if (parsedMapping.context && (parsedMapping.context.projectId !== id || parsedMapping.context.sheetId !== text(body.sheetId))) return jsonError('映射上下文与项目或工作表不匹配');
    if (!['general', 'dataset', 'owned', 'supplier'].includes(text(body.kind) || 'owned')) return jsonError('不支持的数据用途类型');
    const status = text(body.status) || (text(body.spreadsheet) && text(body.sheetId) ? '已连接' : '未连接');
    await d1
      .prepare(
        `INSERT INTO data_sources(id,project_id,type,name,spreadsheet,sheet_id,range,kind,sync_frequency,status,mapping_json,created_at,updated_at)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET
        type=excluded.type,name=excluded.name,spreadsheet=excluded.spreadsheet,sheet_id=excluded.sheet_id,range=excluded.range,kind=excluded.kind,sync_frequency=excluded.sync_frequency,status=excluded.status,mapping_json=excluded.mapping_json,updated_at=excluded.updated_at`
      )
      .bind(
        sourceId,
        id,
        text(body.type) || 'feishu_sheet',
        name,
        text(body.spreadsheet),
        text(body.sheetId),
        text(body.range),
        text(body.kind) || 'owned',
        text(body.syncFrequency) || 'manual',
        status,
        mapping,
        now,
        now
      )
      .run();
    return Response.json({ ok: true, id: sourceId });
  }

  if (action === 'remove_source') {
    const sourceId = text(body.id);
    if (!sourceId) return jsonError('缺少数据源 ID');
    await d1.prepare('DELETE FROM data_sources WHERE id=? AND project_id=?').bind(sourceId, id).run();
    return Response.json({ ok: true });
  }

  if (action === 'manage_member' || action === 'add_member' || action === 'update_member_role' || action === 'remove_member') {
    const targetUserId = text(body.userId);
    const role = text(body.role) || 'viewer';
    const subAction = action === 'remove_member' ? 'remove' : (text(body.subAction) || 'upsert');
    if (!targetUserId) return jsonError('缺少成员用户 ID');

    if (subAction === 'remove') {
      await d1.prepare('DELETE FROM project_members WHERE project_id=? AND user_id=?').bind(id, targetUserId).run();
      return Response.json({ ok: true, removed: true });
    }

    const existingMem = await d1.prepare('SELECT id FROM project_members WHERE project_id=? AND user_id=?').bind(id, targetUserId).first<{ id: string }>();
    if (existingMem) {
      await d1.prepare('UPDATE project_members SET role=?, updated_at=? WHERE id=?').bind(role, now, existingMem.id).run();
      return Response.json({ ok: true, memberId: existingMem.id, role });
    } else {
      const newId = `${id}:${targetUserId}`;
      await d1.prepare('INSERT INTO project_members(id, project_id, user_id, role, created_at, updated_at) VALUES(?, ?, ?, ?, ?, ?)').bind(newId, id, targetUserId, role, now, now).run();
      return Response.json({ ok: true, memberId: newId, role });
    }
  }

  return jsonError('不支持的操作');
}

﻿'use client';

import { usePathname, useSearchParams } from 'next/navigation';
import type { Project } from '../../lib/types/project';
import { CustomSelect } from '../ui/CustomSelect';
import { useProject } from './ProjectContext';

export function ProjectSwitcher({
  projects,
  currentProjectId,
  currentProject,
  loading,
}: {
  projects: Project[];
  currentProjectId: string;
  currentProject: Project | null;
  loading?: boolean;
}) {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const { navigateTo } = useProject();

  function handleChange(nextId: string) {
    if (!nextId || nextId === currentProjectId) return;
    // Maintain current subpath e.g. /projects/qicui/comments -> /projects/other/comments
    const match = window.location.pathname.match(/^\/projects\/[^/]+(\/?.*)$/);
    const subpath = match ? match[1] : '';
    const qs = new URLSearchParams(window.location.search).toString();
    const fullQuery = qs ? '?' + qs : '';
    navigateTo('/projects/' + encodeURIComponent(nextId) + subpath + fullQuery);
  }

  return (
    <div className="project-switcher">
      <small>当前项目</small>
      <div className="switcher-control" style={{ width: '100%', marginTop: 4 }}>
        <CustomSelect
          value={currentProjectId}
          onChange={handleChange}
          ariaLabel="切换项目"
          style={{ width: '100%' }}
          options={projects.length > 0 ? projects.map(p => ({
            value: p.id,
            label: p.name,
            color: p.color || '#2563eb',
          })) : [{ value: currentProjectId, label: loading ? '项目加载中…' : currentProjectId }]}
        />
      </div>
      {currentProject ? (
        <p className="project-subtext">
          {currentProject.brand || '品牌未设置'} · {currentProject.spu || currentProject.name} ·{' '}
          {currentProject.status || '进行中'}
        </p>
      ) : (
        <p className="project-subtext">
          {loading ? '正在同步项目信息…' : '未关联项目资料'}
        </p>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState, useCallback, useMemo, useRef } from 'react';
import type { Project } from '../../lib/types/project';
import { CustomSelect } from '../../components/ui/CustomSelect';
import { LoadingState } from '../../components/ui/LoadingState';
import { EmptyState } from '../../components/ui/EmptyState';
import { ErrorState } from '../../components/ui/ErrorState';
import { api, cnTime, ApiError } from '../../lib/hooks/use-project-data';
import { useProject } from '../../components/project-shell/ProjectContext';
import Link from '../../components/ui/AppLink';
import { CardEditModal, type DashboardCardConfig } from './CardEditModal';
import { CardRenderView } from './CardRenderView';
import type { MetricComputeResult } from '../../lib/metrics/engine';
import { UnsavedChangesDialog } from './UnsavedChangesDialog';
import { ConflictResolutionDialog } from './ConflictResolutionDialog';

interface DatasetSummary {
  id: string;
  name: string;
  rowCount: number;
  columns?: Array<{ key: string; name: string; type: string }>;
  updatedAt: string;
}

interface DatasetDetail {
  id: string; name: string; columns: Array<{ key: string; name: string; type: string }>;
  rowCount: number; rows: Array<Record<string, unknown>>;
  pagination?: { page: number; pageSize: number; total: number; totalPages: number };
}

export function GeneralWorkbenchBoard({
  projectId,
  project,
}: {
  projectId: string;
  project?: Project;
}) {
  const { showToast, navigateTo } = useProject();
  const [datasets, setDatasets] = useState<DatasetSummary[]>([]);
  const [selectedDatasetId, setSelectedDatasetId] = useState<string>('');
  const [detailSnapshot, setDetailSnapshot] = useState<{ key: string; data: DatasetDetail | null; error: string }>({ key: '', data: null, error: '' });

  const [loading, setLoading] = useState(true);
  const [dataError, setDataError] = useState('');
  const [viewMode, setViewMode] = useState<'board' | 'data'>('board');

  // Draft vs Published Cards separation
  const [isEditingBoard, setIsEditingBoard] = useState(false);
  const [dashboardVersion, setDashboardVersion] = useState<number>(1);
  const [dashboardId, setDashboardId] = useState<string>('');
  const [publishedCards, setPublishedCards] = useState<DashboardCardConfig[]>([]);
  const [draftCards, setDraftCards] = useState<DashboardCardConfig[]>([]);
  const [savingBoard, setSavingBoard] = useState(false);

  const saveLock = useRef(false);
  const allowNavigation = useRef(false);
  const workspaceRequest = useRef(0);
  const detailRequest = useRef(0);
  const summaryRequest = useRef(0);
  const metricRequest = useRef(0);
  const [datasetRevision, setDatasetRevision] = useState(0);
  const [pendingNavigation, setPendingNavigation] = useState<string | null>(null);

  // Card modal state
  const [modalCard, setModalCard] = useState<DashboardCardConfig | null>(null);
  const [showCardModal, setShowCardModal] = useState(false);
  const [editingCardIndex, setEditingCardIndex] = useState<number | null>(null);

  // Unsaved changes & conflict dialogs
  const [pendingDatasetSwitch, setPendingDatasetSwitch] = useState<string | null>(null);
  const [showUnsavedDialog, setShowUnsavedDialog] = useState(false);
  const [conflictInfo, setConflictInfo] = useState<{ serverVersion: number; localVersion: number } | null>(null);

  // Metric evaluation results
  const [metricSnapshot, setMetricSnapshot] = useState<{ key: string; results: Record<string, MetricComputeResult>; error: string }>({ key: '', results: {}, error: '' });

  // Table pagination and search
  const [searchTable, setSearchTable] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 15;
  const detailKey = JSON.stringify({ projectId, selectedDatasetId, currentPage, searchTable, datasetRevision });
  const activeDataset = detailSnapshot.key === detailKey ? detailSnapshot.data : null;
  const detailError = detailSnapshot.key === detailKey ? detailSnapshot.error : '';

  const hasUnsavedChanges = useMemo(() => {
    return isEditingBoard && JSON.stringify(draftCards) !== JSON.stringify(publishedCards);
  }, [isEditingBoard, draftCards, publishedCards]);

  // Load datasets and dashboard configuration
  const loadWorkspaceData = useCallback(async () => {
    const requestId = ++workspaceRequest.current;
    try {
      const [dsRes, dashRes] = await Promise.all([
        api<{ ok: boolean; datasets: DatasetSummary[] }>(`/api/datasets?projectId=${encodeURIComponent(projectId)}`),
        api<{
          ok: boolean;
          dashboards: Array<{ id: string; version: number; name: string }>;
          targetDashboardId?: string;
          cards: Array<{ id: string; title: string; type: string; configJson: string; sortOrder: number }>;
        }>(`/api/dashboards?projectId=${encodeURIComponent(projectId)}`),
      ]);

      if (requestId !== workspaceRequest.current) return;
      setDataError('');
      const dsList = dsRes.datasets || [];
      setDatasets(dsList);

      const chosenDsId = dsList[0]?.id || '';
      setSelectedDatasetId(chosenDsId);

      const targetDash = dashRes.dashboards?.find((d) => d.id === dashRes.targetDashboardId) || dashRes.dashboards?.[0];
      if (targetDash) {
        setDashboardId(targetDash.id);
        setDashboardVersion(targetDash.version || 1);
      } else {
        setDashboardId(`dash-${projectId}-default`);
        setDashboardVersion(1);
      }

      // If cards are stored in database for this dashboard, parse them
      if (dashRes.cards) {
        const parsedCards: DashboardCardConfig[] = dashRes.cards.map((c) => {
          let conf: Partial<DashboardCardConfig> & { dimension?: string } = {};
          try { conf = JSON.parse(c.configJson || '{}'); } catch {}
          return {
            ...conf,
            id: c.id,
            title: c.title,
            type: c.type === 'bar_chart' ? 'breakdown' : (c.type as DashboardCardConfig['type']) || 'metric_card',
            groupBy: conf.groupBy || (c.type === 'bar_chart' ? conf.dimension : undefined),
            sortOrder: c.sortOrder,
          };
        });
        setPublishedCards(parsedCards);
        setDraftCards(parsedCards);
      } else if (!dashRes.dashboards?.length) {
        // Initial default install only when no dashboard existed before
        const defaults: DashboardCardConfig[] = [
          { title: '任务总数', type: 'metric_card', metric: 'task_total', unit: '项' },
          { title: '已完成项', type: 'metric_card', metric: 'task_completed', unit: '项' },
          { title: '任务完成率', type: 'progress_card', metric: 'task_completion_rate', unit: '%' },
          { title: '预算执行率', type: 'progress_card', metric: 'budget_spent_rate', unit: '%' },
        ];
        setPublishedCards(defaults);
        setDraftCards(defaults);
      } else {
        // Saved as empty dashboard: stay empty!
        setPublishedCards([]);
        setDraftCards([]);
      }
    } catch (err) {
      if (requestId === workspaceRequest.current) setDataError(err instanceof Error ? err.message : '获取工作台数据失败');
    } finally {
      if (requestId === workspaceRequest.current) setLoading(false);
    }
  }, [projectId]);

  useEffect(() => {
    void loadWorkspaceData();
    return () => { workspaceRequest.current++; detailRequest.current++; metricRequest.current++; };
  }, [loadWorkspaceData]);

  // Load active dataset rows with server-side pagination & search
  const loadDatasetDetail = useCallback(async (dsId: string, page = 1, search = '', requestKey = detailKey) => {
    const requestId = ++detailRequest.current;
    if (!dsId) return;
    try {
      const url = `/api/datasets?projectId=${encodeURIComponent(projectId)}&id=${encodeURIComponent(dsId)}&page=${page}&pageSize=${pageSize}&search=${encodeURIComponent(search)}`;
      const detail = await api<{ ok: boolean; dataset: DatasetDetail }>(url);
      if (requestId !== detailRequest.current) return;
      if (detail.dataset?.pagination && page > detail.dataset.pagination.totalPages) {
        setCurrentPage(Math.max(1, detail.dataset.pagination.totalPages));
        return;
      }
      if (detail.dataset) {
        setDetailSnapshot({ key: requestKey, data: detail.dataset, error: '' });
      }
    } catch (err) {
      if (requestId === detailRequest.current) setDetailSnapshot({ key: requestKey, data: null, error: err instanceof Error ? err.message : '加载数据集记录失败' });
    }
  }, [projectId, detailKey]);

  useEffect(() => {
    if (selectedDatasetId) {
      void loadDatasetDetail(selectedDatasetId, currentPage, searchTable);
    }
  }, [selectedDatasetId, currentPage, searchTable, datasetRevision, loadDatasetDetail]);

  // Data refresh updates summaries and detail independently of dashboard drafts.
  useEffect(() => {
    let cancelled = false;
    const refreshDatasets = async (event?: Event) => {
      const affected = (event as CustomEvent<{ projectId?: string }> | undefined)?.detail?.projectId;
      if (affected && affected !== projectId) return;
      const requestId = ++summaryRequest.current;
      try {
        const response = await api<{ datasets: DatasetSummary[] }>('/api/datasets?projectId=' + encodeURIComponent(projectId));
        if (cancelled || requestId !== summaryRequest.current) return;
        setDatasets(response.datasets);
        setDatasetRevision(r => r + 1);
      } catch (error) {
        if (!cancelled && requestId === summaryRequest.current) setDetailSnapshot(previous => ({ ...previous, error: error instanceof Error ? error.message : '数据刷新失败' }));
      }
    };
    window.addEventListener('app:datasets-changed', refreshDatasets);
    window.addEventListener('focus', refreshDatasets);
    return () => { cancelled = true; window.removeEventListener('app:datasets-changed', refreshDatasets); window.removeEventListener('focus', refreshDatasets); };
  }, [projectId]);

  // Evaluate cards through unified backend metric engine
  const activeCards = isEditingBoard ? draftCards : publishedCards;
  const metricKey = JSON.stringify({ projectId, selectedDatasetId, activeCards, datasetRevision });
  const currentMetrics = metricSnapshot.key === metricKey;
  const metricResults = currentMetrics ? metricSnapshot.results : {};
  const metricError = currentMetrics ? metricSnapshot.error : '';
  const evaluatingMetrics = activeCards.length > 0 && !currentMetrics;

  const evaluateCardsOnServer = useCallback(async (cardsToEval: DashboardCardConfig[]) => {
    const requestId = ++metricRequest.current;
    if (!cardsToEval.length) return;
    try {
      const res = await api<{ ok: boolean; metrics: MetricComputeResult[] }>('/api/metrics', {
        method: 'POST',
        body: JSON.stringify({
          projectId,
          cards: cardsToEval.map((c) => ({
            ...c,
            datasetId: c.datasetId || selectedDatasetId,
          })),
        }),
      });
      if (requestId !== metricRequest.current) return;
      if (res.metrics) {
        const resultsMap: Record<string, MetricComputeResult> = {};
        cardsToEval.forEach((c, idx) => {
          const key = c.id || `card-${idx}`;
          resultsMap[key] = res.metrics[idx];
        });
        setMetricSnapshot({ key: metricKey, results: resultsMap, error: '' });
      }
    } catch (error) {
      if (requestId === metricRequest.current) setMetricSnapshot({ key: metricKey, results: {}, error: error instanceof Error ? error.message : '指标计算失败' });
    }
  }, [projectId, selectedDatasetId, metricKey]);

  useEffect(() => {
    void evaluateCardsOnServer(activeCards);
  }, [activeCards, evaluateCardsOnServer, datasetRevision]);

  // Dataset switching guard
  function requestDatasetSwitch(dsId: string) {
    if (saveLock.current || dsId === selectedDatasetId) return;
    if (hasUnsavedChanges) {
      setPendingDatasetSwitch(dsId);
      setShowUnsavedDialog(true);
    } else {
      setSelectedDatasetId(dsId);
      setCurrentPage(1);
      setSearchTable('');
    }
  }

  // Only a confirmed server snapshot can advance a pending dataset or navigation.
  const saveDashboard = async (force = false): Promise<boolean> => {
    if (saveLock.current) return false;
    saveLock.current = true;
    setSavingBoard(true);
    const snapshot = draftCards.map((c, idx) => ({ id: c.id, title: c.title, type: c.type, metricKeys: c.metric ? [c.metric] : [], config: { ...c, datasetId: c.datasetId || selectedDatasetId }, sortOrder: idx }));
    try {
      const res = await api<{ ok: boolean; dashboardId: string; version: number; cards: Array<{ id: string; title: string; type: string; configJson: string; sortOrder: number }> }>('/api/dashboards', {
        method: 'POST', body: JSON.stringify({ projectId, dashboardId: dashboardId || 'dash-' + projectId + '-default', name: '默认工作台看板', version: dashboardVersion, force, cards: snapshot }),
      });
      const confirmed = res.cards.map(c => ({ ...JSON.parse(c.configJson), id: c.id, title: c.title, type: c.type, sortOrder: c.sortOrder } as DashboardCardConfig));
      setDashboardId(res.dashboardId);
      setDashboardVersion(res.version);
      setPublishedCards(confirmed);
      setDraftCards(confirmed);
      setIsEditingBoard(false);
      setConflictInfo(null);
      showToast('看板已成功保存并发布！', 'success');
      return true;
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        const version = Number(err.data?.serverVersion);
        if (Number.isFinite(version)) setConflictInfo({ serverVersion: version, localVersion: dashboardVersion });
        else showToast('看板冲突响应缺少服务器版本，请保留草稿并重试', 'error');
      } else showToast(err instanceof Error ? err.message : '保存看板失败', 'error');
      return false;
    } finally { saveLock.current = false; setSavingBoard(false); }
  };

  function completePendingSwitch() {
    setShowUnsavedDialog(false);
    if (pendingDatasetSwitch) { setSelectedDatasetId(pendingDatasetSwitch); setCurrentPage(1); setSearchTable(''); setPendingDatasetSwitch(null); }
    if (pendingNavigation) { const target = pendingNavigation; setPendingNavigation(null); allowNavigation.current = true; navigateTo(target); }
  }

  useEffect(() => {
    if (!hasUnsavedChanges && !savingBoard) return;
    const beforeUnload = (e: BeforeUnloadEvent) => { if (allowNavigation.current) return; e.preventDefault(); e.returnValue = ''; };
    const navigation = (e: Event) => {
      if (allowNavigation.current) return;
      const target = (e as CustomEvent<{ href: string }>).detail?.href;
      if (!target || target === window.location.pathname + window.location.search) return;
      e.preventDefault();
      if (!saveLock.current) { setPendingNavigation(target); setShowUnsavedDialog(true); }
    };
    const linkClick = (e: MouseEvent) => {
      const anchor = (e.target as Element).closest?.('a[href]');
      if (!anchor || e.ctrlKey || e.metaKey || e.shiftKey || e.altKey || anchor.getAttribute('target') === '_blank') return;
      const href = anchor.getAttribute('href');
      if (!href || href.startsWith('#')) return;
      e.preventDefault(); e.stopPropagation();
      if (!saveLock.current) { setPendingNavigation(href); setShowUnsavedDialog(true); }
    };
    const protectedHref = window.location.pathname + window.location.search;
    const historyNavigation = (e: PopStateEvent) => {
      if (allowNavigation.current) { allowNavigation.current = false; return; }
      const target = window.location.pathname + window.location.search;
      if (target === protectedHref) return;
      // Restore the protected screen before route subscribers can unmount the draft.
      e.stopImmediatePropagation();
      window.history.pushState(null, '', protectedHref);
      if (!saveLock.current) { setPendingNavigation(target); setShowUnsavedDialog(true); }
    };
    const browserNavigation = (window as Window & { navigation?: EventTarget }).navigation;
    const traversal = (event: Event) => {
      const intent = event as Event & { navigationType?: string; destination?: { url: string } };
      if (intent.navigationType !== 'traverse' || !intent.cancelable || allowNavigation.current || !intent.destination) return;
      const target = new URL(intent.destination.url);
      event.preventDefault();
      if (!saveLock.current) { setPendingNavigation(target.pathname + target.search); setShowUnsavedDialog(true); }
    };
    browserNavigation?.addEventListener('navigate', traversal);
    window.addEventListener('popstate', historyNavigation, true);
    window.addEventListener('beforeunload', beforeUnload);
    window.addEventListener('app:before-navigate', navigation);
    document.addEventListener('click', linkClick, true);
    return () => { browserNavigation?.removeEventListener('navigate', traversal); window.removeEventListener('popstate', historyNavigation, true); window.removeEventListener('beforeunload', beforeUnload); window.removeEventListener('app:before-navigate', navigation); document.removeEventListener('click', linkClick, true); };
  }, [hasUnsavedChanges, savingBoard]);

  function handleCancelEdit() {
    if (saveLock.current) return;
    setDraftCards(publishedCards);
    setIsEditingBoard(false);
  }

  function handleAddCardClick() {
    if (saveLock.current) return;
    setModalCard(null);
    setEditingCardIndex(null);
    setShowCardModal(true);
  }

  function handleEditCardClick(index: number) {
    if (saveLock.current) return;
    setModalCard(draftCards[index]);
    setEditingCardIndex(index);
    setShowCardModal(true);
  }

  function handleSaveCardFromModal(savedCard: DashboardCardConfig) {
    if (saveLock.current) return;
    if (editingCardIndex !== null && editingCardIndex >= 0) {
      const next = [...draftCards];
      next[editingCardIndex] = savedCard;
      setDraftCards(next);
    } else {
      setDraftCards([...draftCards, savedCard]);
    }
    setShowCardModal(false);
    showToast('卡片已更新至本地草稿，请点击右上角「保存并发布看板」', 'info');
  }

  function handleRemoveCard(index: number) {
    if (saveLock.current) return;
    setDraftCards(draftCards.filter((_, i) => i !== index));
  }

  function handleMoveCard(index: number, delta: number) {
    if (saveLock.current) return;
    const nextIdx = index + delta;
    if (nextIdx < 0 || nextIdx >= draftCards.length) return;
    const next = [...draftCards];
    const temp = next[index];
    next[index] = next[nextIdx];
    next[nextIdx] = temp;
    setDraftCards(next);
  }

  const availableColumns = useMemo(() => {
    if (activeDataset?.columns?.length) {
      return activeDataset.columns;
    }
    if (activeDataset?.rows?.length) {
      return Object.keys(activeDataset.rows[0] || {}).map(key => ({ key, name: key, type: 'text' }));
    }
    return [];
  }, [activeDataset]);

  const totalPages = activeDataset?.pagination?.totalPages || 1;
  const totalCount = activeDataset?.pagination?.total ?? activeDataset?.rowCount ?? 0;
  const currentRows = activeDataset?.rows || [];

  if (loading) return <LoadingState text="正在获取工作台数据集与看板…" />;
  if (dataError) return <ErrorState error={dataError} onRetry={loadWorkspaceData} />;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
      {/* Top Header / View & Dataset Bar */}
      <div
        className="workbench-toolbar"
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '14px 18px',
          background: '#ffffff',
          borderRadius: 10,
          border: '1px solid #e2e8f0',
          boxShadow: '0 1px 3px rgba(0,0,0,0.04)',
          flexWrap: 'wrap',
          gap: 12,
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <span style={{ fontSize: 13, fontWeight: 600, color: '#475569' }}>当前业务数据集:</span>
          {datasets.length > 0 ? (
            <CustomSelect
              ariaLabel="当前业务数据集"
              disabled={savingBoard}
              value={selectedDatasetId}
              onChange={requestDatasetSwitch}
              options={datasets.map((d) => ({
                value: d.id,
                label: `${d.name} (${d.rowCount} 行)`,
                badge: cnTime(d.updatedAt),
              }))}
              style={{ width: 280 }}
            />
          ) : (
            <span style={{ fontSize: 13, color: '#94a3b8' }}>暂无导入数据集</span>
          )}
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{ display: 'flex', border: '1px solid #cbd5e1', borderRadius: 6, overflow: 'hidden' }}>
            <button
              onClick={() => setViewMode('board')}
              style={{
                padding: '6px 14px',
                fontSize: 13,
                fontWeight: 600,
                border: 'none',
                cursor: 'pointer',
                background: viewMode === 'board' ? '#2563eb' : '#fff',
                color: viewMode === 'board' ? '#fff' : '#475569',
              }}
            >
              📊 看板视图
            </button>
            <button
              onClick={() => setViewMode('data')}
              style={{
                padding: '6px 14px',
                fontSize: 13,
                fontWeight: 600,
                border: 'none',
                cursor: 'pointer',
                background: viewMode === 'data' ? '#2563eb' : '#fff',
                color: viewMode === 'data' ? '#fff' : '#475569',
              }}
            >
              📋 数据明细 ({totalCount} 行)
            </button>
          </div>

          {viewMode === 'board' && (
            <>
              {isEditingBoard ? (
                <div style={{ display: 'flex', gap: 8 }}>
                  <button
                    disabled={savingBoard}
                    onClick={handleAddCardClick}
                    style={{
                      padding: '6px 12px',
                      fontSize: 13,
                      fontWeight: 600,
                      borderRadius: 6,
                      border: '1px solid #2563eb',
                      background: '#eff6ff',
                      color: '#2563eb',
                      cursor: 'pointer',
                    }}
                  >
                    ＋ 添加卡片
                  </button>
                  <button
                    disabled={savingBoard}
                    onClick={() => saveDashboard(false)}
                    style={{
                      padding: '6px 14px',
                      fontSize: 13,
                      fontWeight: 600,
                      borderRadius: 6,
                      border: 'none',
                      background: '#16a34a',
                      color: '#fff',
                      cursor: 'pointer',
                    }}
                  >
                    {savingBoard ? '正在发布…' : '✓ 保存并发布看板'}
                  </button>
                  <button
                    disabled={savingBoard}
                    onClick={handleCancelEdit}
                    style={{
                      padding: '6px 12px',
                      fontSize: 13,
                      borderRadius: 6,
                      border: '1px solid #cbd5e1',
                      background: '#fff',
                      color: '#64748b',
                      cursor: 'pointer',
                    }}
                  >
                    取消编辑
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => {
                    setDraftCards(publishedCards);
                    setIsEditingBoard(true);
                  }}
                  style={{
                    padding: '6px 14px',
                    fontSize: 13,
                    fontWeight: 600,
                    borderRadius: 6,
                    border: '1px solid #cbd5e1',
                    background: '#fff',
                    color: '#1e293b',
                    cursor: 'pointer',
                  }}
                >
                  ⚙ 自定义看板卡片
                </button>
              )}
            </>
          )}
        </div>
      </div>

      {metricError && <div role="alert">指标计算失败：{metricError}</div>}
      {evaluatingMetrics && <div role="status">正在重新计算指标…</div>}
      {detailError && <ErrorState error={detailError} onRetry={() => loadDatasetDetail(selectedDatasetId, currentPage, searchTable)} />}
      {viewMode === 'board' ? (
        <>
          {datasets.length === 0 ? (
            <EmptyState
              title="当前项目尚未接入通用数据集"
              text="请进入项目设置中的「数据源」配置并同步飞书表格，即可生成动态业务度量看板。"
              action={
                <Link
                  href={`/projects/${encodeURIComponent(projectId)}/settings?tab=data-sources`}
                  style={{ padding: '8px 16px', background: '#2563eb', color: '#fff', borderRadius: 6, textDecoration: 'none', fontSize: 13 }}
                >
                  前往接入数据源 →
                </Link>
              }
            />
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              {isEditingBoard && (
                <div style={{ padding: 12, background: '#fefce8', border: '1px solid #fef08a', borderRadius: 8, fontSize: 13, color: '#854d0e', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span>您正在编辑看板布局。您可以添加卡片、修改指标规则、调整顺序或删除卡片。修改完成后点击「保存并发布看板」。</span>
                  <span style={{ fontSize: 12, color: '#a16207' }}>版本: v{dashboardVersion}</span>
                </div>
              )}

              {activeCards.length === 0 ? (
                <EmptyState
                  title="当前看板未添加任何指标卡片"
                  text={isEditingBoard ? '点击上方「＋ 添加卡片」添加自定义业务度量卡片。' : '点击右上角「⚙ 自定义看板卡片」开始配置个性化指标。'}
                  action={
                    isEditingBoard ? (
                      <button
                        onClick={handleAddCardClick}
                        style={{ padding: '8px 16px', background: '#2563eb', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontSize: 13, fontWeight: 600 }}
                      >
                        ＋ 添加卡片
                      </button>
                    ) : (
                      <button
                        onClick={() => {
                          setDraftCards(publishedCards);
                          setIsEditingBoard(true);
                        }}
                        style={{ padding: '8px 16px', background: '#2563eb', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontSize: 13, fontWeight: 600 }}
                      >
                        ⚙ 自定义看板卡片
                      </button>
                    )
                  }
                />
              ) : (
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: 16 }}>
                  {activeCards.map((card, idx) => {
                    const cardKey = card.id || `card-${idx}`;
                    const metric = metricResults[cardKey];
                    const cardDataset = datasets.find((d) => d.id === (card.datasetId || selectedDatasetId));

                    return (
                      <CardRenderView
                        key={cardKey}
                        card={card}
                        metric={metric}
                        index={idx}
                        totalCards={activeCards.length}
                        isEditing={isEditingBoard && !savingBoard}
                        onMove={(delta) => handleMoveCard(idx, delta)}
                        onEdit={() => handleEditCardClick(idx)}
                        onRemove={() => handleRemoveCard(idx)}
                        datasetName={cardDataset?.name}
                      />
                    );
                  })}
                </div>
              )}
            </div>
          )}
        </>
      ) : (
        /* Data Detail View with Server-Side Pagination and Search */
        <div style={{ background: '#fff', borderRadius: 12, border: '1px solid #e2e8f0', padding: 20 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14, flexWrap: 'wrap', gap: 10 }}>
            <div>
              <h3 style={{ margin: 0, fontSize: 16, color: '#0f172a' }}>数据集记录明细</h3>
              <p style={{ margin: '2px 0 0', fontSize: 12, color: '#64748b' }}>
                查看已从飞书表格同步的结构化原始数据，服务端全量检索与分页。
              </p>
            </div>
            <input
              type="text"
              placeholder="全量搜索记录关键字…"
              value={searchTable}
              onChange={(e) => {
                setSearchTable(e.target.value);
                setCurrentPage(1);
              }}
              style={{ width: 220, padding: '7px 12px', fontSize: 13, borderRadius: 6, border: '1px solid #cbd5e1' }}
            />
          </div>

          {!currentRows.length ? (
            <div style={{ padding: 32, textAlign: 'center', color: '#94a3b8' }}>没有匹配的数据记录</div>
          ) : (
            <div style={{ overflowX: 'auto', border: '1px solid #e2e8f0', borderRadius: 8 }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13, textAlign: 'left' }}>
                <thead>
                  <tr style={{ background: '#f8fafc', borderBottom: '1px solid #e2e8f0' }}>
                    <th style={{ padding: '8px 12px', color: '#64748b' }}>#</th>
                    {availableColumns.map((col) => (
                      <th key={col.key} style={{ padding: '8px 12px', color: '#475569', fontWeight: 600 }}>
                        {col.name}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {currentRows.map((row, rIdx) => (
                    <tr key={rIdx} style={{ borderBottom: '1px solid #f1f5f9' }}>
                      <td style={{ padding: '8px 12px', color: '#94a3b8' }}>
                        {(currentPage - 1) * pageSize + rIdx + 1}
                      </td>
                      {availableColumns.map((col) => (
                        <td key={col.key} style={{ padding: '8px 12px', color: '#1e293b' }}>
                          {String(row[col.key] ?? '—')}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 14 }}>
            <span style={{ fontSize: 12, color: '#64748b' }}>
              共 {totalCount} 条记录 · 第 {currentPage} / {totalPages} 页
            </span>
            <div style={{ display: 'flex', gap: 8 }}>
              <button
                disabled={currentPage <= 1}
                onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                style={{ padding: '4px 10px', fontSize: 12, borderRadius: 4, border: '1px solid #cbd5e1', background: '#fff', cursor: currentPage <= 1 ? 'default' : 'pointer' }}
              >
                上一页
              </button>
              <button
                disabled={currentPage >= totalPages}
                onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                style={{ padding: '4px 10px', fontSize: 12, borderRadius: 4, border: '1px solid #cbd5e1', background: '#fff', cursor: currentPage >= totalPages ? 'default' : 'pointer' }}
              >
                下一页
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Card Creation / Editing Modal */}
      {showCardModal && (
        <CardEditModal
          projectId={projectId}
          initialCard={modalCard}
          datasets={datasets}
          defaultDatasetId={selectedDatasetId}
          onSave={handleSaveCardFromModal}
          onClose={() => setShowCardModal(false)}
        />
      )}

      {/* Unsaved Changes Warning Dialog */}
      <UnsavedChangesDialog
        open={showUnsavedDialog}
        busy={savingBoard}
        onSave={async () => { if (await saveDashboard(false)) completePendingSwitch(); }}
        onDiscard={() => { if (saveLock.current) return; setDraftCards(publishedCards); setIsEditingBoard(false); completePendingSwitch(); }}
        onCancel={() => { if (saveLock.current) return; setShowUnsavedDialog(false); setPendingDatasetSwitch(null); setPendingNavigation(null); }}
      />

      {/* 409 Concurrency Conflict Dialog */}
      <ConflictResolutionDialog
        open={Boolean(conflictInfo)}
        serverVersion={conflictInfo?.serverVersion ?? dashboardVersion}
        localVersion={conflictInfo?.localVersion || dashboardVersion}
        onReload={() => {
          setConflictInfo(null);
          setShowUnsavedDialog(false);
          setPendingDatasetSwitch(null);
          setPendingNavigation(null);
          setIsEditingBoard(false);
          void loadWorkspaceData();
        }}
        busy={savingBoard}
        onForceSave={async () => { if (await saveDashboard(true)) completePendingSwitch(); }}
        onCancel={() => setConflictInfo(null)}
      />
    </div>
  );
}

﻿'use client';

import { contentDirectionLabel } from '../../lib/dashboard-display';
import { useState, type ReactNode } from 'react';
import Link from '../../components/ui/AppLink';
import type { Dashboard, Ops, Project } from '../../lib/types/project';
